options.getOption:
const choices = {
  "freshman": {
    "name": "Freshman",
    "color": "#5794F2"
  },
  "sophomore": {
    "name": "Sophomore",
    "color": "#FF9830"
  },
  "junior": {
    "name": "Junior",
    "color": "#73BF69"
  },
  "senior": {
    "name": "Senior",
    "color": "#B877D9"
  },
  "masters": {
    "name": "Master's student",
    "color": "#56D4DD"
  },
  "phd": {
    "name": "PhD student",
    "color": "#F2495C"
  },
  "other": {
    "name": "Other",
    "color": "#FADE2A"
  },
  "alumni": {
    "name": "Alumni",
    "color": "#FF73CB"
  },
  "nonstudent": {
    "name": "Nonstudent",
    "color": "#8AB8FF"
  },
  "not_provided": {
    "name": "Not provided",
    "color": "#8E8E8E"
  }
};
const fields = context.panel.data.series.flatMap((series) => series.fields.filter((field) => field.type === 'number'));
const rows = fields.every((field) => field.values.length === 1) ? fields.map((field) => {
  const key = field.labels?.answer || field.name;
  const choice = Object.hasOwn(choices, key) ? choices[key] : { name: key, color: '#8AB8FF' };
  return { ...choice, count: field.values[0] };
}) : [];
const theme = context.grafana.theme;
const textColor = theme.colors.text.primary;
const labelColor = theme.isDark ? '#FFFFFF' : textColor;

if (rows.length === 0 || rows.some((row) => !Number.isSafeInteger(row.count) || row.count < 0)) {
  return { graphic: { type: 'text', left: 'center', top: 'middle', style: { text: 'Unavailable', fill: textColor } } };
}

const maximum = Math.max(1, ...rows.map((row) => row.count));
const summary = (row) => `{count|${row.count}}`;
const detail = (row) => `${row.name}\nUsers: ${row.count}`;
const track = rows.map(() => maximum);
const carrier = {
  type: 'bar', barGap: '-100%', barWidth: '80%', barMaxWidth: 40,
  data: track, silent: true, z: 3,
  itemStyle: { color: 'transparent' }, tooltip: { show: false }, emphasis: { disabled: true },
};
return {
  animation: false,
  backgroundColor: 'transparent',
  aria: { enabled: true, label: { description: rows.map(detail).join(', ') } },
  grid: { left: 4, right: 4, top: 4, bottom: 4 },
  xAxis: { type: 'value', min: 0, max: maximum, show: false },
  yAxis: { type: 'category', inverse: true, data: rows.map((row) => row.name), show: false },
  legend: { show: false },
  tooltip: {
    trigger: 'axis', renderMode: 'richText', confine: true,
    formatter: (parameters) => detail(rows[parameters[0].dataIndex]),
  },
  series: [
    {
      name: 'Users', type: 'bar', barWidth: '80%', barMaxWidth: 40, z: 2,
      showBackground: true, backgroundStyle: { color: theme.colors.background.secondary },
      data: rows.map((row) => ({ value: row.count, itemStyle: { color: row.color, opacity: theme.isDark ? 0.4 : 0.2 } })),
      emphasis: { disabled: true },
    },
    { ...carrier, label: { show: true, position: 'insideLeft', color: labelColor, fontSize: 16, formatter: (parameters) => rows[parameters.dataIndex].name } },
    { ...carrier, label: { show: true, position: 'insideRight', color: labelColor, fontSize: 16, rich: { count: { fontSize: 18, fontWeight: 600, lineHeight: 20 } }, formatter: (parameters) => summary(rows[parameters.dataIndex]) } },
  ],
};
